import java.math.BigInteger

fun main() {
    val (n, k) = readLine()!!.split(" ").map { it.toLong() }

    if (n == 1L) {
        println(0)
        return
    }

    if (k == 1) { // k >= 2 per constraints, but handle anyway
        println(-1)
        return
    }

    // max sum using 1..(k-1) splitters is sum_{i=2}^k (i-1) = k(k-1)/2
    // max additional pipes = k(k-1)/2
    // total pipes = 1 + k(k-1)/2
    if (n - 1 > k * (k - 1) / 2) {
        println(-1)
        return
    }

    // Binary search for minimum m (number of splitters)
    // such that sum of m largest distinct values from {1, 2, ..., k-1} >= n - 1
    // Sum of m largest = (k-1) + (k-2) + ... + (k-m) = m * (2k - m - 1) / 2
    var low = 1L
    var high = k - 1
    var ans = -1L

    while (low <= high) {
        val mid = (low + high) / 2
        // Calculate sum = mid * (2*k - mid - 1) / 2
        // Use BigInteger to avoid overflow, though Kotlin Long might suffice for n <= 1e18?
        // k <= 1e9, mid <= 1e9. mid * (2k) <= 2e18 < 9e18 (Long.MAX_VALUE).
        // But intermediate calculation might overflow signed 64-bit? 
        // max mid = 1e9. max 2k = 2e9. product = 2e18. Long.MAX_VALUE = 9.22e18. Safe.
        val sum = mid * (2 * k - mid - 1) / 2
        if (sum >= n - 1) {
            ans = mid
            high = mid - 1
        } else {
            low = mid + 1
        }
    }

    println(ans)
}
